export function buildApplePayButton(
  buttonStyle: "black" | "white",
  locale: string,
  host: Element,
): HTMLElement {
  ensureApplePaySdk();

  const radius =
    getComputedStyle(host).getPropertyValue("--radius").trim() || "0.625rem";

  const btn = document.createElement("apple-pay-button");
  btn.setAttribute(STRIPE_BRANDED_MARKER, "apple_pay");
  btn.setAttribute("buttonstyle", buttonStyle);
  btn.setAttribute("type", "plain");
  btn.setAttribute("locale", locale);
  btn.style.cssText = [
    `--apple-pay-button-width: 100%`,
    `--apple-pay-button-height: 2.75rem`,
    `--apple-pay-button-border-radius: ${radius}`,
    `--apple-pay-button-padding: 0px 0px`,
    `--apple-pay-button-box-sizing: border-box`,
    "display: block",
    "width: 100%",
    "height: 2.75rem",
  ].join("; ");

  return btn;
}

function buildGooglePayButton(
  buttonStyle: "black" | "white",
  locale: string,
  host: Element,
): HTMLElement {
  const btn = document.createElement("google-pay-button") as HTMLElement & {
    environment: google.payments.api.Environment;
    buttonColor: google.payments.api.ButtonColor;
    buttonType: google.payments.api.ButtonType;
    buttonSizeMode: google.payments.api.ButtonSizeMode;
    buttonBorderType: google.payments.api.ButtonBorderType;
    buttonLocale: string;
    buttonRadius: number;
    paymentRequest: google.payments.api.PaymentDataRequest;
  };

  btn.setAttribute(STRIPE_BRANDED_MARKER, "google_pay");
  btn.environment = "TEST";
  btn.buttonColor = buttonStyle;
  btn.buttonType = "plain";
  btn.buttonSizeMode = "fill";
  btn.buttonBorderType = "no_border";
  btn.buttonLocale = locale.split("-")[0];
  btn.buttonRadius = resolveRadiusPx(host);
  btn.paymentRequest = {
    apiVersion: 2,
    apiVersionMinor: 0,
    allowedPaymentMethods: [
      {
        type: "CARD",
        parameters: {
          allowedAuthMethods: ["PAN_ONLY", "CRYPTOGRAM_3DS"],
          allowedCardNetworks: [
            "AMEX",
            "DISCOVER",
            "JCB",
            "MASTERCARD",
            "VISA",
          ],
        },
      },
    ],
    merchantInfo: { merchantName: "Checkout" },
    transactionInfo: {
      totalPrice: "0",
      totalPriceStatus: "ESTIMATED",
      currencyCode: "USD",
    },
  };

  // overflow:hidden clips the inner button to exactly our border-radius,
  // ensuring it matches the rest of the design system.
  btn.style.cssText = [
    "display: block",
    "width: 100%",
    "height: 2.75rem",
    "border-radius: var(--radius, 0.625rem)",
    "overflow: hidden",
  ].join("; ");

  return btn;
}

function buildBrandedButton(
  type: string,
  config: BrandedButtonConfig,
): HTMLButtonElement {
  const btn = document.createElement("button");
  btn.type = "button";
  btn.setAttribute("aria-label", config.ariaLabel);
  btn.setAttribute(STRIPE_BRANDED_MARKER, type);
  btn.style.cssText = [
    `background: ${config.background}`,
    "width: 100%",
    "height: 2.75rem",
    "border: none",
    "cursor: pointer",
    "border-radius: var(--radius, 0.625rem)",
    "display: flex",
    "align-items: center",
    "justify-content: center",
    "gap: 0.5rem",
    "padding: 0 1rem",
  ].join("; ");
  btn.innerHTML = config.content;
  return btn;
}

export function isKnownStripeBrandType(type: string | null): boolean {
  if (!type) return false;
  return (
    type === "apple_pay" ||
    type === "google_pay" ||
    type === "revolut_pay" ||
    type === "klarna" ||
    type === "venmo" ||
    type === "eps" ||
    type === "ideal" ||
    type === "bancontact" ||
    type === "blik" ||
    type === "przelewy24" ||
    type === "affirm" ||
    type === "afterpay_clearpay" ||
    !!BRAND_CONFIGS[type]
  );
}

export type StripeBrandedButtonOptions = {
  locale: string;
  buttonStyle: "black" | "white";
};

export function renderStripeBrandedButton(
  type: string | null,
  shadow: ShadowRoot,
  host: Element,
  options: StripeBrandedButtonOptions,
): void {
  const existing = shadow.querySelector(`[${STRIPE_BRANDED_MARKER}]`);

  const isKnown =
    type === "apple_pay" ||
    type === "google_pay" ||
    type === "revolut_pay" ||
    type === "klarna" ||
    type === "venmo" ||
    type === "eps" ||
    type === "ideal" ||
    type === "bancontact" ||
    type === "blik" ||
    type === "przelewy24" ||
    type === "affirm" ||
    type === "afterpay_clearpay" ||
    !!(type && BRAND_CONFIGS[type]);

  if (!isKnown) {
    if (existing) existing.remove();
    host.removeAttribute("data-stripe-brand");
    return;
  }

  if (existing && existing.getAttribute(STRIPE_BRANDED_MARKER) === type) {
    if (type === "apple_pay") {
      if (existing.getAttribute("buttonstyle") !== options.buttonStyle) {
        existing.setAttribute("buttonstyle", options.buttonStyle);
      }
      if (existing.getAttribute("locale") !== options.locale) {
        existing.setAttribute("locale", options.locale);
      }
    } else if (type === "google_pay") {
      const el = existing as HTMLElement & {
        buttonColor: string;
        buttonLocale: string;
      };
      const lang = options.locale.split("-")[0];
      if (el.buttonColor !== options.buttonStyle)
        el.buttonColor = options.buttonStyle;
      if (el.buttonLocale !== lang) el.buttonLocale = lang;
    } else if (type === "revolut_pay") {
      if (existing.getAttribute("data-button-style") !== options.buttonStyle) {
        existing.remove();
        shadow.appendChild(buildRevolutButton(options.buttonStyle));
      }
    } else if (type === "klarna") {
      if (existing.getAttribute("data-button-style") !== options.buttonStyle) {
        existing.remove();
        shadow.appendChild(buildKlarnaButton(options.buttonStyle));
      }
    } else if (type === "venmo") {
      if (existing.getAttribute("data-button-style") !== options.buttonStyle) {
        existing.remove();
        shadow.appendChild(buildVenmoButton(options.buttonStyle));
      }
    } else if (type === "eps") {
      if (existing.getAttribute("data-button-style") !== options.buttonStyle) {
        existing.remove();
        shadow.appendChild(buildEpsButton(options.buttonStyle));
      }
    } else if (type === "ideal") {
      if (existing.getAttribute("data-button-style") !== options.buttonStyle) {
        existing.remove();
        shadow.appendChild(buildIdealButton(options.buttonStyle));
      }
    } else if (type === "bancontact") {
      if (existing.getAttribute("data-button-style") !== options.buttonStyle) {
        existing.remove();
        shadow.appendChild(buildBancontactButton(options.buttonStyle));
      }
    } else if (type === "blik") {
      if (existing.getAttribute("data-button-style") !== options.buttonStyle) {
        existing.remove();
        shadow.appendChild(buildBlikButton(options.buttonStyle));
      }
    } else if (type === "przelewy24") {
      if (existing.getAttribute("data-button-style") !== options.buttonStyle) {
        existing.remove();
        shadow.appendChild(buildPrzelewy24Button(options.buttonStyle));
      }
    } else if (type === "affirm") {
      if (existing.getAttribute("data-button-style") !== options.buttonStyle) {
        existing.remove();
        shadow.appendChild(buildAffirmButton(options.buttonStyle));
      }
    } else if (type === "afterpay_clearpay") {
      if (existing.getAttribute("data-button-style") !== options.buttonStyle) {
        existing.remove();
        shadow.appendChild(buildAfterpayButton(options.buttonStyle));
      }
    }
    return;
  }

  if (existing) existing.remove();

  let btn: HTMLElement;
  if (type === "apple_pay") {
    btn = buildApplePayButton(options.buttonStyle, options.locale, host);
  } else if (type === "google_pay") {
    btn = buildGooglePayButton(options.buttonStyle, options.locale, host);
  } else if (type === "revolut_pay") {
    btn = buildRevolutButton(options.buttonStyle);
  } else if (type === "klarna") {
    btn = buildKlarnaButton(options.buttonStyle);
  } else if (type === "venmo") {
    btn = buildVenmoButton(options.buttonStyle);
  } else if (type === "eps") {
    btn = buildEpsButton(options.buttonStyle);
  } else if (type === "ideal") {
    btn = buildIdealButton(options.buttonStyle);
  } else if (type === "bancontact") {
    btn = buildBancontactButton(options.buttonStyle);
  } else if (type === "blik") {
    btn = buildBlikButton(options.buttonStyle);
  } else if (type === "przelewy24") {
    btn = buildPrzelewy24Button(options.buttonStyle);
  } else if (type === "affirm") {
    btn = buildAffirmButton(options.buttonStyle);
  } else if (type === "afterpay_clearpay") {
    btn = buildAfterpayButton(options.buttonStyle);
  } else {
    btn = buildBrandedButton(type, BRAND_CONFIGS[type]);
  }

  shadow.appendChild(btn);
  host.setAttribute("data-stripe-brand", type);
}

export function cleanupStripeBrandedButton(
  shadow: ShadowRoot,
  host: Element,
): void {
  const existing = shadow.querySelector(`[${STRIPE_BRANDED_MARKER}]`);
  if (existing) existing.remove();
  host.removeAttribute("data-stripe-brand");
}
